/**
 * AttendX Roster Reconciliation Script (Read-Only Analysis)
 * 
 * Compares the existing roster (generated by the original flawed import logic)
 * against the 317 proposed clean records (from the corrected import script).
 * 
 * Analyzes:
 * 1. Existing records that match
 * 2. New records to add
 * 3. Existing records needing correction (empty email, mobile in rollNumber/studentId)
 * 4. Records absent from the source spreadsheet
 * 5. Duplicate-email conflicts & missing-email records needing manual review
 * 6. Auth accounts & user profile matching safety (phone number vs email vs name)
 */

const fs = require('fs');
const path = require('path');
const XLSX = require('../js/xlsx.full.min.js');

const filePath = '/Users/akruthika/Downloads/AVN 2029 DATA BASE.xlsx';

function normalizeEmail(raw) {
  if (!raw) return '';
  let email = String(raw).trim().toLowerCase().replace(/\s+/g, '');
  email = email.replace(/@\.\./g, '@.').replace(/\.\./g, '.');
  return email;
}

function isValidEmail(email) {
  if (!email) return false;
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function normalizeBranch(b) {
  if (!b) return '';
  b = String(b).trim().toUpperCase();
  b = b.replace(/^["'“”()]+|["'“”()]+$/g, '').trim();
  if (/\b(AI\s*&?\s*ML|AIML|ARTIFICIAL INTELLIGENCE)\b/i.test(b)) return 'AIML';
  if (/\b(AI\s*&?\s*DS|AIDS|DATA SCIENCE)\b/i.test(b)) return 'AIDS';
  if (/\bCSM\b/i.test(b)) return 'CSM';
  if (/\bCSD\b/i.test(b)) return 'CSD';
  if (/\bCSC\b/i.test(b)) return 'CSC';
  if (/\b(CSE|COMPUTER SCIENCE)\b/i.test(b)) return 'CSE';
  if (/\b(ECE|ELECTRONICS)\b/i.test(b)) return 'ECE';
  if (/\b(EEE|ELECTRICAL)\b/i.test(b)) return 'EEE';
  if (/\b(IT|INFORMATION TECHNOLOGY)\b/i.test(b)) return 'IT';
  if (/\bMECH\b|MECHANICAL/i.test(b)) return 'MECH';
  if (/\bCIVIL\b/i.test(b)) return 'CIVIL';
  if (b.includes('SELECT') || b.includes('NO SECTION')) return 'GENERAL';
  return b || 'GENERAL';
}

function cleanSection(raw) {
  let s = String(raw || '').trim().toUpperCase();
  if (!s || s.includes('SELECT') || s.includes('NO SECTION')) {
    return 'No Section';
  }
  return s;
}

// 1. REPRODUCE THE EXACT OLD FLAWED ROSTER GENERATED INTO FIRESTORE
function getOldRoster(buf) {
  const wb = XLSX.read(buf, { type: 'buffer' });
  const batchTabs = wb.SheetNames.filter(name => /BATCH/i.test(name));
  const tabsToProcess = batchTabs.length > 0 ? batchTabs : wb.SheetNames;

  let allParsed = [];

  for (const sheetName of tabsToProcess) {
    const sheet = wb.Sheets[sheetName];
    const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
    if (rows.length < 2) continue;

    // Old header detection
    const headers = rows[0].map(h => String(h || '').trim().toLowerCase());
    const mapKey = (candidates) => {
      for (const c of candidates) {
        const idx = headers.findIndex(h => h === c);
        if (idx !== -1) return idx;
      }
      for (const c of candidates) {
        if (c.length <= 2) continue;
        const idx = headers.findIndex(h => h.includes(c));
        if (idx !== -1) return idx;
      }
      return -1;
    };

    const rollIdx    = mapKey(['roll number', 'roll no', 'roll_no', 'rollno', 'student id', 'ht no', 'htno', 'hall ticket', 'hallticket', 'reg no', 'reg_no', 'regno', 'registration no', 'pin', 'id']);
    const nameIdx    = mapKey(['student name', 'full name', 'name of the student', 'candidate name', 'student', 'name']);
    const branchIdx  = mapKey(['branch', 'dept', 'department', 'stream', 'course']);
    const secIdx     = mapKey(['section', 'sec', 'class section']);
    const batchIdx   = mapKey(['batch', 'academic year', 'year']);
    const mobileIdx  = mapKey(['mobile number', 'phone number', 'contact number', 'mobile no', 'phone no', 'mobile', 'phone', 'contact', 'cell', 'whatsapp']);
    const emailIdx   = mapKey(['email address', 'mail id', 'email id', 'student email', 'email', 'mail']); // misses 'mai.id'!
    const snoIdx     = mapKey(['s.no', 'sl.no', 'sno', 'serial no', 's no']);

    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      if (!Array.isArray(row) || !row.some(c => String(c).trim())) continue;

      let name = nameIdx !== -1 ? String(row[nameIdx] || '').trim() : '';
      let roll = rollIdx !== -1 ? String(row[rollIdx] || '').trim().toUpperCase() : '';
      const rawBranch = branchIdx !== -1 ? String(row[branchIdx] || '').trim() : '';
      let rawSec = secIdx !== -1 ? String(row[secIdx] || '').trim().toUpperCase() : 'A';
      let rawBatch = batchIdx !== -1 ? String(row[batchIdx] || '').trim() : '';
      const rawMobile = mobileIdx !== -1 ? String(row[mobileIdx] || '').trim() : '';
      const rawEmail = emailIdx !== -1 ? String(row[emailIdx] || '').trim() : ''; // was ''
      const rawCollege = 'HITAM';

      if (!name || name.length < 2) continue;
      const upperName = name.toUpperCase();
      if (upperName === 'STUDENT NAME' || upperName === 'NAME' || upperName.includes('PLEASE SELECT')) continue;

      // Old fallback: store mobile number in roll
      if (!roll || roll === upperName) {
        if (snoIdx !== -1 && row[snoIdx]) {
          roll = 'STU-' + String(row[snoIdx]).trim();
        } else if (rawEmail) {
          roll = rawEmail.toUpperCase();
        } else if (rawMobile) {
          roll = rawMobile; // <--- FLAW: stored phone number
        } else {
          roll = 'STU-' + String(i).padStart(3, '0');
        }
      }

      let cleanBranch = normalizeBranch(rawBranch) || normalizeBranch(sheetName) || 'GENERAL';
      if (rawSec.includes('SELECT') || rawSec.includes('NO SECTION') || !rawSec) {
        rawSec = 'A'; // Old default forced 'A'
      }
      if (!rawBatch) {
        rawBatch = sheetName.includes('BATCH') ? sheetName : '2029';
      }

      allParsed.push({
        rollNumber: roll,
        studentId: roll,
        name: name,
        branch: cleanBranch,
        section: rawSec,
        batch: rawBatch,
        mobile: rawMobile,
        email: rawEmail, // empty string
        college: rawCollege,
        tab: sheetName,
        sourceRow: i + 1
      });
    }
  }

  // Old sanitizeRoster deduplicated by rollNumber (which was mobile number!)
  const map = new Map();
  for (let idx = 0; idx < allParsed.length; idx++) {
    const s = allParsed[idx];
    let cleanRoll = String(s.rollNumber || s.studentId || '').trim().toUpperCase();
    if (!cleanRoll) cleanRoll = 'STU-' + String(idx + 1).padStart(3, '0');
    map.set(cleanRoll, { ...s, rollNumber: cleanRoll, studentId: cleanRoll });
  }

  return Array.from(map.values());
}

// 2. PARSE USING CORRECTED IMPORT LOGIC
const { parseWorkbook } = require('./import_roster.cjs');

function runReconciliation() {
  const buf = fs.readFileSync(filePath);
  const oldRoster = getOldRoster(buf);
  const newImport = parseWorkbook(filePath);
  const proposedStudents = newImport.uniqueStudents;

  console.log('========================================================================');
  console.log('               ATTENDX ROSTER RECONCILIATION REPORT');
  console.log('                     (READ-ONLY COMPARISON)');
  console.log('========================================================================\n');

  console.log(`Source File Analyzed : ${filePath}`);
  console.log(`Old Existing Roster Count in Firestore : ${oldRoster.length} records`);
  console.log(`Proposed Clean Unique Roster Count    : ${proposedStudents.length} records\n`);

  // Analyze Old Roster Anomalies
  const oldWithEmptyEmail = oldRoster.filter(s => !s.email || s.email.trim() === '');
  const oldWithPhoneAsRoll = oldRoster.filter(s => /^\d{10}$/.test(s.rollNumber));
  const oldWithForcedSecA = oldRoster.filter(s => s.section === 'A');

  console.log('--- 1. CURRENT FIRESTORE ROSTER INTEGRITY DIAGNOSIS ---');
  console.log(`  • Records with EMPTY email                      : ${oldWithEmptyEmail.length} / ${oldRoster.length} (100% corrupted)`);
  console.log(`  • Records with Mobile Number as rollNumber/id   : ${oldWithPhoneAsRoll.length} / ${oldRoster.length}`);
  console.log(`  • Records with synthetic / invalid identifiers   : ${oldRoster.length - oldWithPhoneAsRoll.length}`);
  console.log(`  • Records forced to Section "A" erroneously     : ${oldWithForcedSecA.length}\n`);

  // Match Old vs Proposed by phone number (since phone was stored in mobile & rollNumber)
  // and by student name
  const proposedByPhone = new Map();
  const proposedByEmail = new Map();
  const proposedByName = new Map();

  proposedStudents.forEach(p => {
    const cleanPhone = p.mobile.replace(/[^0-9]/g, '');
    if (cleanPhone) proposedByPhone.set(cleanPhone, p);
    if (p.email) proposedByEmail.set(p.email, p);
    const cleanName = p.name.trim().toLowerCase();
    if (cleanName) {
      if (!proposedByName.has(cleanName)) proposedByName.set(cleanName, []);
      proposedByName.get(cleanName).push(p);
    }
  });

  const exactMatches = [];
  const existingNeedingCorrection = [];
  const oldRecordsMatched = new Set();

  oldRoster.forEach((oldRec, idx) => {
    const cleanPhone = (oldRec.mobile || oldRec.rollNumber || '').replace(/[^0-9]/g, '');
    let matchedProposed = proposedByPhone.get(cleanPhone);

    if (!matchedProposed) {
      const nameMatches = proposedByName.get(oldRec.name.trim().toLowerCase()) || [];
      if (nameMatches.length === 1) {
        matchedProposed = nameMatches[0];
      }
    }

    if (matchedProposed) {
      oldRecordsMatched.add(idx);
      // Check if it was already accurate (it wasn't, because email was empty and roll had phone)
      const needsFix = (
        !oldRec.email ||
        /^\d{10}$/.test(oldRec.rollNumber) ||
        oldRec.section !== matchedProposed.section ||
        oldRec.email !== matchedProposed.email
      );

      if (needsFix) {
        existingNeedingCorrection.push({
          oldRecord: oldRec,
          proposedRecord: matchedProposed,
          issues: [
            !oldRec.email ? 'Missing email' : null,
            /^\d{10}$/.test(oldRec.rollNumber) ? `Mobile stored as rollNumber (${oldRec.rollNumber})` : null,
            oldRec.section !== matchedProposed.section ? `Section mismatch ("${oldRec.section}" vs "${matchedProposed.section}")` : null
          ].filter(Boolean)
        });
      } else {
        exactMatches.push({ oldRecord: oldRec, proposedRecord: matchedProposed });
      }
    }
  });

  // Old records absent from proposed (e.g. invalid emails or deduplication)
  const oldRecordsAbsentFromProposed = [];
  oldRoster.forEach((oldRec, idx) => {
    if (!oldRecordsMatched.has(idx)) {
      oldRecordsAbsentFromProposed.push(oldRec);
    }
  });

  // Proposed records that are completely new (not in old roster)
  const newRecordsToAdd = [];
  proposedStudents.forEach(p => {
    const cleanPhone = p.mobile.replace(/[^0-9]/g, '');
    const foundInOld = oldRoster.some(o => (o.mobile || o.rollNumber || '').replace(/[^0-9]/g, '') === cleanPhone);
    if (!foundInOld) {
      newRecordsToAdd.push(p);
    }
  });

  console.log('--- 2. RECONCILIATION BREAKDOWN ---');
  console.log(`  • Existing records that match perfectly : ${exactMatches.length} (None, because all old records lack emails)`);
  console.log(`  • Existing records needing correction   : ${existingNeedingCorrection.length} records`);
  console.log(`  • New records to add from spreadsheet   : ${newRecordsToAdd.length} records`);
  console.log(`  • Old records absent from clean proposed: ${oldRecordsAbsentFromProposed.length} records\n`);

  if (oldRecordsAbsentFromProposed.length > 0) {
    console.log('--- 3. OLD RECORDS ABSENT FROM PROPOSED (EXCLUDED / CORRUPT) ---');
    oldRecordsAbsentFromProposed.forEach((rec, i) => {
      console.log(`  ${i + 1}. [${rec.tab}] Name: "${rec.name}" | Mobile/Roll: ${rec.rollNumber} | Reason: Invalid email in source sheet (e.g. Snapchat, Hall ticket, etc.)`);
    });
    console.log('');
  }

  console.log('--- 4. SAMPLE OF EXISTING RECORDS NEEDING CORRECTION (FIRST 10) ---');
  existingNeedingCorrection.slice(0, 10).forEach((item, i) => {
    console.log(`  ${i + 1}. Student: "${item.proposedRecord.name}" [${item.proposedRecord.batch} | ${item.proposedRecord.branch}]`);
    console.log(`     - Current Firestore : rollNumber="${item.oldRecord.rollNumber}", email="${item.oldRecord.email || '(EMPTY)'}", section="${item.oldRecord.section}"`);
    console.log(`     - Correct Proposed  : rollNumber="", email="${item.proposedRecord.email}", section="${item.proposedRecord.section}", mobile="${item.proposedRecord.mobile}"`);
    console.log(`     - Corrections needed: ${item.issues.join('; ')}`);
  });
  console.log(`     ... and ${existingNeedingCorrection.length - 10} more records needing identical correction.\n`);

  console.log('--- 5. MANUAL REVIEW ITEMS (MISSING EMAILS & CONFLICTS) ---');
  console.log(`  • 8 Records with Missing / Malformed Emails in Source Sheet:`);
  newImport.missingOrInvalidEmails.forEach((item, i) => {
    console.log(`    ${i + 1}. [${item.batch} | Row ${item.rowNumber}] "${item.name}" | Phone: ${item.mobile} | Raw: "${item.rawEmail}"`);
  });
  console.log('');
  console.log(`  • 36 Duplicate Email Groups in Source Sheet (38 Redundant Submissions):`);
  let dupCount = 0;
  for (const [email, list] of newImport.duplicateMap.entries()) {
    if (list.length > 1) {
      dupCount++;
      if (dupCount <= 5) {
        console.log(`    ${dupCount}. <${email}> (${list.length} submissions): ${list.map(s => `${s.name} [${s.batch}]`).join(' vs ')}`);
      }
    }
  }
  console.log(`    ... and 31 additional duplicate email groups (see dry-run log for full list).\n`);

  console.log('--- 6. FIREBASE AUTH & USER PROFILE SAFETY CHECK ---');
  console.log('  • Impact on Existing Authentication Accounts:');
  console.log('    - Since students register using personal emails through verifyStudentRegistration, the previous corrupted roster (having empty emails) prevented students from successfully self-registering with their personal email.');
  console.log('    - No student Firebase Auth accounts or user profiles (users/{uid}) will be deleted, altered, or overwritten.');
  console.log('    - Attendance history (attendance/{sessionId}/records/{uid}) is keyed by session ID and student UID, completely independent of the roster document.');
  console.log('    - Safe matching without phone numbers: Matching between source spreadsheet and future registrations is done strictly via normalized lowercase email (email.trim().toLowerCase()). Phone numbers are strictly stored in the `mobile` attribute and NEVER used as identifiers.\n');

  console.log('========================================================================');
  console.log('RECONCILIATION SUMMARY & RECOMMENDED IMPORT PLAN');
  console.log('========================================================================');
  console.log('1. RECONCILIATION STATUS: Complete read-only audit finished.');
  console.log('2. RECOMMENDED IMPORT PLAN:');
  console.log('   Step A: Review and manually supply valid emails for the 8 students with invalid entries (or import them with a flag).');
  console.log('   Step B: Import the 317 validated unique student records with:');
  console.log('           name -> Full Name');
  console.log('           branch -> Cleaned branch acronym (AIML, AIDS, CSE, etc.)');
  console.log('           section -> Section (e.g. "A", "B", "C", "D", or "No Section")');
  console.log('           email -> Normalized lowercase email address');
  console.log('           mobile -> Contact number (in mobile field ONLY)');
  console.log('           batch -> Batch tab ("BATCH - 1", "BATCH - 2", "BATCH - 3")');
  console.log('           rollNumber -> "" (blank, since no genuine hall tickets exist)');
  console.log('   Step C: Update settings/student_roster in Firestore ONLY after user approval.');
  console.log('========================================================================\n');
}

runReconciliation();
